return articles.map(a => ({ json: a }));

// ── FMCG Deal Keywords ──────────────────────────────────────
const FMCG_BRANDS = [
  'unilever','nestle','nestlé','pepsico','coca-cola','procter','gamble','p&g',
  'mars','mondelez','kraft','heinz','danone','ab inbev','diageo','reckitt',
  'colgate','palmolive','campbell','general mills','kellogg','hershey',
  'ferrero','carlsberg','heineken','smucker','conagra','clorox',
  // Indian FMCG
  'hindustan unilever','hul','dabur','marico','itc','tata consumer','godrej',
  'emami','britannia','haldiram','amul','patanjali','wipro consumer',
  'bajaj consumer','pidilite','jyothy','zydus wellness',
];

const DEAL_KEYWORDS = [
  'acqui', 'merger', 'merger', 'takeover', 'buyout', 'invest', 'joint venture',
  'partnership', 'divest', 'spin-off', 'stake', 'funding', 'deal', 'bid',
  'transaction', 'purchase', 'buys', 'sells', 'selling', 'buying',
];

// ── Levenshtein distance for fuzzy title matching ────────────
function levenshtein(a, b) {
  const m = a.length, n = b.length;
  const dp = Array.from({ length: m + 1 }, (_, i) =>
    Array.from({ length: n + 1 }, (_, j) => (i === 0 ? j : j === 0 ? i : 0))
  );
  for (let i = 1; i <= m; i++)
    for (let j = 1; j <= n; j++)
      dp[i][j] = a[i-1] === b[j-1] ? dp[i-1][j-1]
               : 1 + Math.min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]);
  return dp[m][n];
}

function isSimilarTitle(t1, t2, threshold = 0.85) {
  const a = t1.toLowerCase().trim();
  const b = t2.toLowerCase().trim();
  if (a === b) return true;
  const maxLen = Math.max(a.length, b.length);
  if (maxLen === 0) return true;
  const similarity = 1 - (levenshtein(a, b) / maxLen);
  return similarity >= threshold;
}

function isFmcgRelevant(title, content) {
  const text = (title + ' ' + (content || '')).toLowerCase();
  const hasBrand = FMCG_BRANDS.some(b => text.includes(b));
  const hasDeal  = DEAL_KEYWORDS.some(k => text.includes(k));
  return hasBrand && hasDeal;
}

// ── Process each article ─────────────────────────────────────
const seenTitles = [];
const results = [];

for (const item of items) {
  const art = item.json;
  const title = art.title || '';
  const content = art.content || '';

  // Check fuzzy title duplicate against already-seen titles
  const isDup = seenTitles.some(prev => isSimilarTitle(prev, title));

  const isRelevant = isFmcgRelevant(title, content);

  if (!isDup) seenTitles.push(title);

  results.push({
    json: {
      id: art.id,
      is_duplicate: isDup,
      is_relevant: !isDup && isRelevant,
      _title: title,
      _reason: isDup ? 'duplicate_title' : (!isRelevant ? 'irrelevant' : 'ok'),
    }
  });
}

console.log(`Processed ${results.length}: dups=${results.filter(r=>r.json.is_duplicate).length}, irrelevant=${results.filter(r=>!r.json.is_relevant && !r.json.is_duplicate).length}`);
return results;
